export class Periods {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's periods by from-date, shared with whoever shows a claim's period. */
  readonly periods = model<Period[]>([]);
  /** The date and figure of each claim that counts. */
  readonly dues = input.required<DatedDue[]>();

  protected readonly nameInput = signal('');
  protected readonly fromInput = signal('');
  protected readonly toInput = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly generateFrom = signal('');
  protected readonly generateTo = signal('');
  /** How many periods the last generate made; null before one, and while one runs. */
  protected readonly generated = signal<number | null>(null);
  protected readonly generateError = signal<string | null>(null);
  /** The error of each period's last refused action, by period id. */
  protected readonly rowErrors = signal<ReadonlyMap<number, string>>(new Map());
  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;

  constructor() {
    // Re-read the sheet's periods from the store every time a sheet is loaded.
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.periods.set([]);
      this.nameInput.set('');
      this.fromInput.set('');
      this.toInput.set('');
      this.error.set(null);
      this.generateFrom.set('');
      this.generateTo.set('');
      this.generated.set(null);
      this.generateError.set(null);
      this.rowErrors.set(new Map());
      if (sheet) {
        void this.fetch(sheet);
      }
    });
  }

  protected dueTotalOf(p: Period): string {
    return periodDueTotal(p, this.dues());
  }

  /** Close a period, fixing its due-total; the server refuses a role the permission matrix does
   *  not allow, and a period already closed. */
  protected close(p: Period): Promise<void> {
    return this.act(p, 'close', (status) =>
      status === 403
        ? 'Your role may not close period ' + p.name + '.'
        : status === 409
          ? 'Period ' + p.name + ' is already closed.'
          : 'Could not close period ' + p.name + '.',
    );
  }

  /** Soft-close a period, fixing its figures while its claims can still change; the server refuses
   *  a role the permission matrix does not allow to close, and a period already closed or soft-closed. */
  protected softClose(p: Period): Promise<void> {
    return this.act(p, 'soft-close', (status) =>
      status === 403
        ? 'Your role may not close period ' + p.name + '.'
        : status === 409
          ? 'Period ' + p.name + ' is already closed.'
          : 'Could not soft-close period ' + p.name + '.',
    );
  }

  /** Reopen a closed or soft-closed period, making its due-total live again; the server refuses a role the
   *  permission matrix does not allow, and a period that is not closed. */
  protected reopen(p: Period): Promise<void> {
    return this.act(p, 'reopen', (status) =>
      status === 403
        ? 'Your role may not reopen period ' + p.name + '.'
        : status === 409
          ? 'Period ' + p.name + ' is not closed.'
          : 'Could not reopen period ' + p.name + '.',
    );
  }

  /** Take an action on a period's row, showing the error the server's refusal maps to. */
  private async act(p: Period, action: string, refusal: (status: number) => string): Promise<void> {
    this.rowErrors.update((m) => {
      if (!m.has(p.id)) return m;
      const next = new Map(m);
      next.delete(p.id);
      return next;
    });
    const sheet = this.session.sheet();
    try {
      const changed = await firstValueFrom(
        this.http.post<Period>('/api/periods/' + action, { sheet, user: this.session.user(), id: p.id }),
      );
      if (this.session.sheet() !== sheet) return;
      this.periods.update((list) => list.map((x) => (x.id === changed.id ? changed : x)));
    } catch (e) {
      if (this.session.sheet() !== sheet) return;
      const err = refusal(e instanceof HttpErrorResponse ? e.status : 0);
      this.rowErrors.update((m) => new Map(m).set(p.id, err));
    }
  }

  private async fetch(sheet: string): Promise<void> {
    try {
      const list = await firstValueFrom(this.http.post<Period[]>('/api/periods/list', { sheet }));
      if (this.session.sheet() === sheet) this.periods.set(list);
    } catch {
      this.error.set('Could not read the periods on this sheet.');
    }
  }

  protected async save(event: Event): Promise<void> {
    event.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const sheet = this.session.sheet();
    const name = this.nameInput().trim();
    const from = this.fromInput().trim() || this.session.today() || '';
    const to = this.toInput().trim();
    if (!/^\S+$/.test(name)) {
      this.error.set('Enter a name for the period, without spaces.');
      return;
    }
    if (this.periods().some((p) => p.name.toLowerCase() === name.toLowerCase())) {
      this.error.set('That period name is already in use on this sheet.');
      return;
    }
    if (!DATE.test(from) || Number.isNaN(Date.parse(from)) || !DATE.test(to) || Number.isNaN(Date.parse(to))) {
      this.error.set('Enter the from and to dates as yyyy-mm-dd.');
      return;
    }
    if (to < from) {
      this.error.set('The to-date cannot be before the from-date.');
      return;
    }
    if (this.periods().some((p) => p.from <= to && from <= p.to)) {
      this.error.set('That period overlaps another period.');
      return;
    }
    this.submitting = true;
    try {
      const added = await firstValueFrom(
        this.http.post<Period>('/api/periods/add', { sheet, user: this.session.user(), name, from, to }),
      );
      if (this.session.sheet() !== sheet) return;
      this.periods.update((list) => [...list, added].sort((a, b) => a.from.localeCompare(b.from)));
      this.nameInput.set('');
      this.fromInput.set('');
      this.toInput.set('');
    } catch (e) {
      this.error.set(
        e instanceof HttpErrorResponse && e.status === 409
          ? 'That period name is in use, or the period overlaps another.'
          : 'Could not add this period.',
      );
    } finally {
      this.submitting = false;
    }
  }

  /** Make one period per calendar month from the from-date's month to the to-date's month, leaving
   *  out a month whose name is in use or whose days overlap a period; shows how many were made. */
  protected async generate(event: Event): Promise<void> {
    event.preventDefault();
    if (this.submitting) return;
    this.generateError.set(null);
    this.generated.set(null);
    const sheet = this.session.sheet();
    const from = this.generateFrom().trim() || this.session.today() || '';
    const to = this.generateTo().trim();
    if (!DATE.test(from) || Number.isNaN(Date.parse(from)) || !DATE.test(to) || Number.isNaN(Date.parse(to))) {
      this.generateError.set('Enter the from and to dates as yyyy-mm-dd.');
      return;
    }
    if (to < from) {
      this.generateError.set('The to-date cannot be before the from-date.');
      return;
    }
    this.submitting = true;
    try {
      const made = await firstValueFrom(
        this.http.post<Period[]>('/api/periods/generate', { sheet, user: this.session.user(), from, to }),
      );
      if (this.session.sheet() !== sheet) return;
      this.periods.update((list) => [...list, ...made].sort((a, b) => a.from.localeCompare(b.from)));
      this.generated.set(made.length);
    } catch (e) {
      if (this.session.sheet() !== sheet) return;
      this.generateError.set(
        e instanceof HttpErrorResponse && e.status === 403
          ? 'Your role may not add periods.'
          : 'Could not generate the periods.',
      );
    } finally {
      this.submitting = false;
    }
  }
}
import { Component, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { People } from '../people/people';

// The one screen: sign in by name, then load a sheet by id. Everything else hangs off the
// active sheet.
@Component({
  selector: 'app-home',
  imports: [People],
  template: `
    @if (session.user(); as user) {
      <section aria-label="Session">
        <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>
        <form (submit)="load($event)">
          <label for="sheet-id-input">Sheet id</label>
          <input
            id="sheet-id-input"
            data-testid="sheet-id-input"
            [value]="sheetInput()"
            (input)="sheetInput.set($any($event.target).value); sheetError.set(null)"
          />
          <button type="submit" data-testid="sheet-load">Load</button>
          @if (sheetError(); as err) {
            <p role="alert" data-testid="sheet-error">{{ err }}</p>
          }
        </form>
        @if (session.sheet(); as sheet) {
          <p>Sheet <strong data-testid="sheet-current-id">{{ sheet }}</strong></p>
          <form aria-label="Sheet today" (submit)="saveToday($event)">
            <p>Today <strong data-testid="sheet-today">{{ session.today() }}</strong></p>
            <label for="sheet-today-input">Change today</label>
            <input
              id="sheet-today-input"
              type="date"
              data-testid="sheet-today-input"
              [value]="todayInput()"
              (input)="todayInput.set($any($event.target).value); sheetError.set(null)"
            />
            <button type="submit" data-testid="sheet-today-save">Set today</button>
          </form>
          <p>
            Archived <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong>
            <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>
          </p>
          <form aria-label="As of" (submit)="setAsOf($event)">
            <p>As of <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong></p>
            <label for="asof-date">Show as of</label>
            <input
              id="asof-date"
              type="date"
              data-testid="asof-date"
              [value]="asOfInput()"
              (input)="asOfInput.set($any($event.target).value); asOfError.set(null)"
            />
            <button type="submit" data-testid="asof-set">Set as of</button>
            <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
            @if (asOfError(); as err) {
              <p role="alert" data-testid="asof-error">{{ err }}</p>
            }
          </form>
          <app-people />
        } @else {
          <p data-testid="sheet-none">No sheet loaded.</p>
        }
      </section>
    } @else {
      <form aria-label="Sign in" (submit)="signIn($event)">
        <label for="signin-name">Your name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set($any($event.target).value); signinError.set(null)"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signinError(); as err) {
          <p role="alert" data-testid="signin-error">{{ err }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly signinError = signal<string | null>(null);
  protected readonly sheetError = signal<string | null>(null);
  protected readonly todayInput = signal('');
  protected readonly asOfInput = signal('');
  protected readonly asOfError = signal<string | null>(null);

  protected async signIn(event: Event): Promise<void> {
    event.preventDefault();
    this.signinError.set(null);
    const name = this.nameInput().trim();
    if (!name) {
      this.signinError.set('Enter a name to sign in.');
      return;
    }
    try {
      await this.session.signIn(name);
    } catch {
      this.signinError.set('Could not sign in.');
    }
  }

  protected async load(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(null);
    const id = this.sheetInput().trim();
    if (!id) {
      this.sheetError.set('Enter a sheet id to load.');
      return;
    }
    try {
      await this.session.loadSheet(id);
    } catch {
      this.sheetError.set('Could not load that sheet.');
    }
  }

  protected async saveToday(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(null);
    const today = this.todayInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.sheetError.set('Enter a date for today.');
      return;
    }
    try {
      await this.session.setToday(today);
    } catch {
      this.sheetError.set('Could not change the sheet\'s today.');
    }
  }

  protected async setAsOf(event: Event): Promise<void> {
    event.preventDefault();
    this.asOfError.set(null);
    const date = this.asOfInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.asOfError.set('Enter a date to show the sheet as of.');
      return;
    }
    try {
      await this.session.setAsOf(date);
    } catch {
      this.asOfError.set('Could not show the sheet as of that date.');
    }
  }

  protected async clearAsOf(): Promise<void> {
    this.asOfError.set(null);
    try {
      await this.session.clearAsOf();
    } catch {
      this.asOfError.set('Could not show the sheet as it is now.');
    }
  }

  protected async archive(): Promise<void> {
    this.sheetError.set(null);
    try {
      await this.session.archive();
    } catch {
      this.sheetError.set('Could not archive the sheet.');
    }
  }
}

